require "digest"

class HashRing
  def initialize(nodes, replicas)
    @replicas = replicas
    @ring = {}
    @sorted_points = []
    nodes.each { |n| add_node(n) }
  end

  def add_node(node)
    @replicas.times do |i|
      point = Digest::MD5.hexdigest("#{node}:#{i}").to_i(16)
      @ring[point] = node
    end
    @sorted_points = @ring.keys.sort
  end

  def remove_node(node)
    @replicas.times do |i|
      point = Digest::MD5.hexdigest("#{node}:#{i}").to_i(16)
      @ring.delete(point)
    end
    @sorted_points = @ring.keys.sort
  end

  def get_node(key)
    point = Digest::MD5.hexdigest(key).to_i(16)
    idx = @sorted_points.bsearch_index { |p| p >= point }
    idx ||= 0
    @ring[@sorted_points[idx]]
  end
end

